using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;
public static class ValidateCopingScenes
{
 public static string Main()
 {
  if(Application.isPlaying)throw new Exception("Stop Play Mode first");var checks=new List<object>();Action<string,bool>check=(name,passed)=>checks.Add(new{name,passed});var paths=new[]{ProjectWait.M.Editor.ElevatorCopingSetup.Original,ProjectWait.M.Editor.ElevatorCopingSetup.TestScene};
  foreach(var path in paths)
  {
   var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);Physics.SyncTransforms();var l=Object.FindFirstObjectByType<ElevatorLesson>();var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var tag=path==paths[0]?"Original: ":"Test: ";
   check(tag+"Saved scene opens cleanly",!scene.isDirty&&l&&l.scenario);check(tag+"Correct interaction mode",l.scenario.objectGuidedScene==(path==paths[1]));check(tag+"No missing scripts",all.All(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)==0));check(tag+"No temporary runtime dependencies",!AssetDatabase.GetDependencies(path,true).Any(p=>p.Contains("/CodexTemp/")));
   var canvases=all.SelectMany(t=>t.GetComponents<Canvas>()).ToArray();check(tag+"All canvases are world space",canvases.Length>0&&canvases.All(c=>c.renderMode==RenderMode.WorldSpace));check(tag+"Screen HUD stays hidden",!l.view.spatial.hud.gameObject.activeSelf);check(tag+"World dialogue has overlay materials",l.view.GetComponentsInChildren<TMP_Text>(true).All(t=>t.fontSharedMaterial&&t.fontSharedMaterial.shader.name.Contains("Overlay")));
   var up=l.transform.Find("SportsCentre_Interactions/3F_Lobby_Up_Unavailable").GetComponent<ElevatorObservation>();var down=l.transform.Find("SportsCentre_Interactions/3F_Lobby_Call").GetComponent<ElevatorObservation>();check(tag+"Upper XR call disabled",!up.GetComponent<UnityEngine.XR.Interaction.Toolkit.Interactables.XRSimpleInteractable>().enabled);check(tag+"Down call has its own small collider",Mathf.Abs(down.transform.position.y-9.1f)<.001f&&down.GetComponent<BoxCollider>().size.y<.2f);check(tag+"Down-only highlight geometry",down.shapeHighlight.shells.Length==4&&down.shapeHighlight.shells.All(r=>r.transform.position.y<9.2f));
   var f=l.GetComponent<ElevatorCharacterPerformance>();check(tag+"Normal and replacement face meshes assigned",f.faceRenderer&&f.normalFaceMesh&&f.panicFaceMesh&&f.panicFaceMesh.vertexCount==f.normalFaceMesh.vertexCount);check(tag+"Skin preserved while expression is hidden",f.panicFaceMesh.triangles.Length>f.normalFaceMesh.triangles.Length*.9f&&f.panicFaceMesh.triangles.Length<f.normalFaceMesh.triangles.Length);check(tag+"No whites or covers in replacement expression",!f.panicFace.GetComponentsInChildren<Transform>(true).Any(t=>t.name.Contains("EyeWhite")||t.name.Contains("MouthCover")));check(tag+"Expression is black spiral and wavy lines",f.panicFace.GetComponentsInChildren<LineRenderer>(true).Length==3&&f.panicFace.GetComponentsInChildren<LineRenderer>(true).All(r=>r.sharedMaterial.GetColor("_BaseColor").maxColorComponent<.01f));check(tag+"Normal expression initially shown",f.faceRenderer.sharedMesh==f.normalFaceMesh&&!f.panicFace.gameObject.activeSelf);
   check(tag+"Staff participates in direct interaction",l.CollectObservations().Any(o=>o.clue==ElevatorClue.Rescuer)&&l.scenario.hints.Any(h=>h.observation.clue==ElevatorClue.Rescuer));check(tag+"Fixed hint references valid",l.scenario.hints.Length>=14&&l.scenario.hints.All(h=>h&&h.observation&&h.label&&h.group));check(tag+"Physical buttons have feedback",l.CollectObservations().Where(o=>o.gameObject.activeInHierarchy&&(o.clue==ElevatorClue.LobbyCall||o.clue==ElevatorClue.FloorButtons||o.clue==ElevatorClue.FrontFloorButtons||o.clue==ElevatorClue.Intercom)).All(o=>o.feedback&&o.feedback.pulseRenderers.Length==1));
   var barriers=l.transform.Find("Scenario_TransparentBoundaries");check(tag+"Nine invisible boundary walls saved",barriers&&barriers.GetComponentsInChildren<BoxCollider>().Length==9&&barriers.GetComponentsInChildren<Renderer>().Length==0);var fx=l.GetComponent<ElevatorCameraEffects>();check(tag+"Shake pivot wraps tracked camera",fx&&fx.shakePivot&&l.playerCamera.transform.IsChildOf(fx.shakePivot));check(tag+"Pause is world space and initially hidden",l.pauseMenu.canvas.renderMode==RenderMode.WorldSpace&&!l.pauseMenu.canvas.gameObject.activeSelf);check(tag+"No missing active materials",all.Where(t=>t.gameObject.activeInHierarchy).SelectMany(t=>t.GetComponents<Renderer>()).All(r=>r.sharedMaterials.All(m=>m&&m.shader&&m.shader.isSupported)));
  }
  check("Original and test scene GUIDs are different",AssetDatabase.AssetPathToGUID(paths[0])!=AssetDatabase.AssetPathToGUID(paths[1]));check("Normal time and audio restored",Time.timeScale==1&&!AudioListener.pause);check("Original render pipeline restored",!AssetDatabase.GetAssetPath(GraphicsSettings.currentRenderPipeline).StartsWith("Assets/M/Arts/Rendering/"));
  var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success=checks.All(x=>(bool)x.GetType().GetProperty("passed").GetValue(x)),passed=checks.Count(x=>(bool)x.GetType().GetProperty("passed").GetValue(x)),checks,paths,physicalHMDTested=false,completedUtc=DateTime.UtcNow.ToString("o")},Newtonsoft.Json.Formatting.Indented);File.WriteAllText("Assets/M/CodexTemp/ElevatorCoping_20261030~/SavedSceneValidation.json",report);return report;
 }
}
